net.coobird.thumbnailator.ThumbnailParameter param = new net.coobird.thumbnailator.ThumbnailParameter(
        new java.awt.Dimension(50, 50),
        null,
        true,
        "jpg",
        net.coobird.thumbnailator.ThumbnailParameter.DEFAULT_FORMAT_TYPE,
        net.coobird.thumbnailator.ThumbnailParameter.DEFAULT_QUALITY,
        java.awt.image.BufferedImage.TYPE_INT_ARGB,
        null,
        net.coobird.thumbnailator.resizers.Resizers.PROGRESSIVE,
        true,
        true
);

java.io.ByteArrayInputStream is = new java.io.ByteArrayInputStream(new byte[0]);
java.io.ByteArrayOutputStream os = new java.io.ByteArrayOutputStream();
net.coobird.thumbnailator.tasks.StreamThumbnailTask task = new net.coobird.thumbnailator.tasks.StreamThumbnailTask(param, is, os);

net.coobird.thumbnailator.ThumbnailParameter retrievedParam = task.getParam();

assert retrievedParam != null : "Retrieved parameter should not be null";
assert retrievedParam.getSize().width == 50 : "Width should be 50";
assert retrievedParam.getSize().height == 50 : "Height should be 50";
assert "jpg".equals(retrievedParam.getOutputFormat()) : "Output format should be jpg";

System.out.println("__CHECK__ getParam " + retrievedParam.getSize().width + "x" + retrievedParam.getSize().height + " " + retrievedParam.getOutputFormat());

